using System;using System.Collections.Generic;
namespace UnityEngine{public static class Time{public static float realtimeSinceStartup;}public struct Vector3{public Vector3(float x,float y,float z){}}public struct Bounds{public Bounds(Vector3 p,Vector3 s){}}}namespace UnityEngine.Scripting{}
class Entity{}class EntityAlive:Entity{public Class EntityClass=new();public bool Dead;public bool IsDead()=>Dead;public EntityAlive GetAttackTarget()=>null;}class Class{public bool bIsEnemyEntity;}
class EntityPlayerLocal:EntityAlive{public World world;public bool Spawned=true;public Vars Buffs=new();public UnityEngine.Vector3 position;}
class Vars{public Dictionary<string,float> Values=new();public float GetCustomVar(string s)=>Values.TryGetValue(s,out var v)?v:0;}
class World{public EntityPlayerLocal Player;public bool Hostile;public EntityPlayerLocal GetPrimaryPlayer()=>Player;public void GetEntitiesInBounds(Type t,UnityEngine.Bounds b,List<Entity> list){if(Hostile)list.Add(new EntityAlive{EntityClass=new Class{bIsEnemyEntity=true}});}}
class GameManager{public static GameManager Instance=new();public World World;}
class RebirthJournalEntry{public string Id;public bool Read,Dismissed,ReadingOnly;}
static class RebirthPurgeReleasePolicy{public static bool Enabled=true;}class RebirthSandboxOptionManager{public static RebirthSandboxOptionManager Current=new();public bool IsPurge=true;}
class Receipt{public string Biome;public int Tier;}
static class RebirthPurgeMilestoneService{public static Dictionary<string,Receipt> PublishedAll=new();}
static class RebirthPurgeMilestoneNotification{public static bool RestoreReading(EntityPlayerLocal p,string b,int t)=>true;}
static class RebirthJournalGuideService{public static Dictionary<string,RebirthJournalEntry> Entries=new();public static RebirthJournalEntry ObservePurgeGuide(EntityPlayerLocal p,string id){if(!Entries.TryGetValue(id,out var e))Entries[id]=e=new(){Id=id};return e;}public static bool IsPurgeDismissed(RebirthJournalEntry e)=>e.Dismissed;public static bool IsRead(RebirthJournalEntry e)=>e.Read;public static bool IsPurgeReadingOnly(RebirthJournalEntry e)=>e.ReadingOnly;public static void SetPurgeReadingOnly(EntityPlayerLocal p,string id,bool value)=>ObservePurgeGuide(p,id).ReadingOnly=value;public static bool TryGetUnlockedPurgeGuides(EntityPlayerLocal p,out List<RebirthJournalEntry> e,bool all){e=new(Entries.Values);return true;}}
class Topic{public string Sprite="art";}static class RebirthPurgeInformationTopics{public static Topic Find(string id)=>new();public static void UnlockReadingRecipe(EntityPlayerLocal p,Topic t){}public static void Request(EntityPlayerLocal p,string id)=>RebirthPurgeInformationService.Request(p,id,"art");}
class Manager{public bool Modal,Input;public bool IsInputActive()=>Input;public bool IsModalWindowOpen()=>Modal;}
class LocalPlayerUI{public static LocalPlayerUI Current=new();public Manager windowManager=new();public object xui=new();public static LocalPlayerUI GetUIForPlayer(EntityPlayerLocal p)=>Current;}
static class XUiC_RebirthPurgeInformation{public static bool Success=true;public static List<string> Opened=new();public static bool Open(object x,RebirthJournalEntry e,string s){if(!Success)return false;Opened.Add(e.Id);e.Read=true;return true;}}
static class Program{static int n;static void Check(bool ok,string s){if(!ok)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}static EntityPlayerLocal Fresh(){RebirthPurgeInformationService.Reset();RebirthJournalGuideService.Entries.Clear();XUiC_RebirthPurgeInformation.Opened.Clear();XUiC_RebirthPurgeInformation.Success=true;UnityEngine.Time.realtimeSinceStartup=0;LocalPlayerUI.Current=new();var w=new World();w.Player=new(){world=w};GameManager.Instance.World=w;RebirthJournalGuideService.ObservePurgeGuide(w.Player,"PurgeIntro").Read=true;return w.Player;}static void Tick(){UnityEngine.Time.realtimeSinceStartup+=1;RebirthPurgeInformationService.Pulse();}
static void Main(){var p=Fresh();LocalPlayerUI.Current.windowManager.Modal=true;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"modal defers live teaching");LocalPlayerUI.Current.windowManager.Modal=false;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Contains("Help"),"deferred live teaching resumes");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"completed teaching not repeated");
p=Fresh();GameManager.Instance.World.Hostile=true;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"hostile defers teaching");GameManager.Instance.World.Hostile=false;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"safe state resumes teaching");
p=Fresh();RebirthJournalGuideService.ObservePurgeGuide(p,"Help").Dismissed=true;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"dismissed automatic help withheld");RebirthPurgeInformationService.Request(p,"Help","art",true);Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"manual reread of dismissed help allowed");
p=Fresh();RebirthPurgeInformationService.Request(p,"Help","art",notBefore:4);RebirthPurgeInformationService.RestoreReadingOnly(p,"Help");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"live delay preserved during late restoration");for(int i=0;i<3;i++)Tick();Check(XUiC_RebirthPurgeInformation.Opened.Contains("Help"),"late silent restoration cannot cancel live teaching");
p=Fresh();p.Buffs.Values["_rbPurgeSupplyKnown"]=1;p.Buffs.Values["_rbPurgeSupplyDeliveredAny"]=1;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Contains("PurgeSupplyUpdate"),"delivered account recovers first supply help");RebirthPurgeInformationService.Reset();Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"read supply recovery remains once only after reset");p=Fresh();XUiC_RebirthPurgeInformation.Success=false;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0&&!RebirthJournalGuideService.Entries["Help"].Read,"failed window opening preserves unread state");XUiC_RebirthPurgeInformation.Success=true;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"failed window opening retries pending request");
p=Fresh();LocalPlayerUI.Current.windowManager.Input=true;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"active input defers teaching");RebirthPurgeInformationService.Reset();LocalPlayerUI.Current.windowManager.Input=false;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Contains("Help"),"unread Journal restores deferred request after service reset");
p=Fresh();p.Dead=true;RebirthPurgeInformationService.Request(p,"Help","art");Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==0,"dead player cannot receive popup");p.Dead=false;Tick();Check(XUiC_RebirthPurgeInformation.Opened.Count==1,"living player resumes deferred popup");Console.WriteLine("RESULT "+n+" PASS; exact production service extract; native Journal/UI/world providers doubled; no game runtime claim.");}}
